<?php require_once 'bootstrap.php';$tok=(string)($_GET['token']??'');$st=db()->prepare('SELECT * FROM certificates WHERE verify_token=?');$st->execute([$tok]);$c=$st->fetch();if(!$c){http_response_code(404);exit('Attestato non trovato');}?><!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=h($c['title'])?></title><style>body{font-family:Arial,sans-serif;background:#070709;color:#FFFFFF;margin:0;padding:30px}.cert{max-width:850px;margin:auto;background:#101116;border:6px solid #D4AF37;padding:50px;text-align:center;box-shadow:0 16px 40px rgba(0,0,0,0.8), 0 0 30px rgba(212,175,55,0.2)}.gold{color:#D4AF37}.sic{font-family:monospace;color:#a1a1aa}@media print{@page{size:A4 landscape;margin:12mm}button{display:none}body{padding:0;background:#fff;color:#000}.cert{box-shadow:none;border-color:#000;background:#fff}}button{background:linear-gradient(135deg, #FFF2B2, #D4AF37);color:#070709;border:0;padding:12px 24px;border-radius:12px;font-weight:800;cursor:pointer;margin-top:20px}</style></head><body><div class="cert"><p class="gold"><b>DEPENDEX · TRAGUARDI VIVI</b></p><h1 style="color:#FFFFFF;"><?=h($c['title'])?></h1><p style="color:#d1d5db;">Attestato digitale di traguardo</p><h2 style="color:#D4AF37;"><?=h($c['certificate_type'])?></h2><p style="color:#a1a1aa;">Emesso il <?=h($c['issued_at'])?></p><p class="sic"><?=h($c['sic_id'])?></p><p class="sic">Verification token: <?=h($c['verify_token'])?></p><button onclick="print()">Stampa / PDF</button></div></body></html>